                Log.Error(string.Concat("[", GetType().Name, "]", " GetAllData: ", ex.ToString()));
                return StatusCode(Convert.ToInt32(HttpStatusCode.InternalServerError), ConstantHelper.Message.InternalServer);
            }
        }

        /// <summary>BOT-1.2 (Catalog 220): admin liên kết tay tài khoản / nhân viên với Telegram user id trên 1 bot (đã xác minh trực tiếp → Active, không cần mã).</summary>
        [AdminOnly]
        [HttpPost("Link")]
        public async Task<IActionResult> Link([FromForm] IdentityLinkRequest request)
        {
            try
            {
                return Ok(await _link.AdminLink(request));
