                return StatusCode(Convert.ToInt32(HttpStatusCode.InternalServerError), ConstantHelper.Message.InternalServer);
            }
        }

        /// <summary>BOT-1.2 (Catalog 220): admin gỡ liên kết (→ Revoked, bot ngừng phục vụ, không cấp token).</summary>
        [AdminOnly]
        [HttpPost("Unlink")]
        public async Task<IActionResult> Unlink([FromForm] Guid id)
        {
            try
            {
                return Ok(await _link.AdminUnlink(id));
            }
            catch (Exception ex)
            {
                Log.Error(string.Concat("[", GetType().Name, "]", " Unlink: ", ex.ToString()));
                return StatusCode(Convert.ToInt32(HttpStatusCode.InternalServerError), ConstantHelper.Message.InternalServer);
